// Build ONE weekly digest item from the quote ledger. Nothing here is sent to a customer.
const cfg = $('⚙️ Your settings').first().json;

const pad = (n) => String(n).padStart(2, '0');
const ymd = (d) => d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());

// Parse YYYY-MM-DD as LOCAL midnight. new Date('YYYY-MM-DD') is UTC midnight, which lands on
// the previous calendar day in UTC-minus timezones (US/Canada) and shifts every day count by one.
// Out-of-range parts are rejected instead of rolling over: '2026-13-05' is a typo, not next January.
const parseLocalDate = (raw) => {
  const s = String(raw || '').trim();
  const m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  if (!m) return new Date(s);
  const y = +m[1], mo = +m[2], da = +m[3];
  const d = new Date(y, mo - 1, da);
  if (d.getFullYear() !== y || d.getMonth() !== mo - 1 || d.getDate() !== da) return new Date(NaN);
  return d;
};

// 'today' comes from $now so day counts follow the workflow timezone (Settings -> Timezone).
const nowTz = $now;
const today = new Date(nowTz.year, nowTz.month - 1, nowTz.day);

// Monday of the current week, local time. This key is what makes the digest go out once a week.
const weekStart = new Date(today);
weekStart.setDate(weekStart.getDate() - ((weekStart.getDay() + 6) % 7));
const weekKey = ymd(weekStart);

// A date written to Sheets can come back reformatted (7/27/2026, or a full timestamp), so normalise
// whatever the log returns before comparing. A raw string compare here would silently re-send.
// Slash dates are ambiguous (7/27/2026 vs 27/7/2026), so BOTH readings count as a match -
// safer to block a resend than to double-send because of a locale guess.
const toWeekKeys = (raw) => {
  const s = String(raw == null ? '' : raw).trim();
  if (!s) return [];
  const iso = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (iso) return [iso[1] + '-' + pad(+iso[2]) + '-' + pad(+iso[3])];
  const slash = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (slash) return [slash[3] + '-' + pad(+slash[1]) + '-' + pad(+slash[2]), slash[3] + '-' + pad(+slash[2]) + '-' + pad(+slash[1])];
  const d = new Date(s);
  return isNaN(d.getTime()) ? [] : [ymd(d)];
};

// An empty log sheet arrives as one blank item, which simply matches nothing.
const alreadySent = $('Read the digest log').all().some((r) => toWeekKeys(r.json.week_start).includes(weekKey));

const nudgeDays = Number(cfg.nudgeDays) || 7;
const coldDays = Number(cfg.coldDays) || 21;
const sym = cfg.currencySymbol || '$';

// Accept both 1,234.56 and 1.234,56 — whichever separator comes last is the decimal point.
const toNumber = (raw) => {
  let s = String(raw == null ? '' : raw).replace(/[^0-9.,-]/g, '').trim();
  if (!s) return 0;
  const dec = Math.max(s.lastIndexOf('.'), s.lastIndexOf(','));
  s = (dec > -1 && s.length - dec <= 3)
    ? s.slice(0, dec).replace(/[.,]/g, '') + '.' + s.slice(dec + 1).replace(/[.,]/g, '')
    : s.replace(/[.,]/g, '');
  const n = Number(s);
  return isNaN(n) ? 0 : n;
};

const rows = [];
let skipped = 0;
for (const item of $('Read all quotes').all()) {
  const q = item.json;
  if (String(q.status || '').trim().toLowerCase() !== 'open') continue;
  if (!q.sent_date) { skipped++; continue; }
  const sent = parseLocalDate(q.sent_date);
  if (isNaN(sent.getTime())) { skipped++; continue; }
  sent.setHours(0, 0, 0, 0);
  // round, not floor: both sides are local midnights, and floor undercounts by one across a DST spring-forward
  const days = Math.round((today - sent) / 86400000);
  if (days < 0) { skipped++; continue; } // a sent_date in the future is a typo, not a stale quote
  rows.push({
    quote_id: String(q.quote_id || ''),
    customer_name: String(q.customer_name || '(no name)'),
    amount: toNumber(q.quote_amount),
    days,
    bucket: days >= coldDays ? 'cold' : (days >= nudgeDays ? 'nudge' : 'fresh'),
  });
}
rows.sort((a, b) => (b.amount - a.amount) || (b.days - a.days));

const cold = rows.filter((r) => r.bucket === 'cold');
const nudge = rows.filter((r) => r.bucket === 'nudge');
const fresh = rows.filter((r) => r.bucket === 'fresh');
const valueAtRisk = cold.concat(nudge).reduce((s, r) => s + r.amount, 0);

const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const fmt = (n) => sym + n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const cell = 'padding:6px 10px;border-bottom:1px solid #eee';
const head = 'padding:6px 10px;border-bottom:2px solid #ddd';

const section = (title, note, list) => {
  if (!list.length) return '';
  const trs = list.map((r) =>
    '<tr><td style="' + cell + '">' + esc(r.customer_name) + '</td>'
    + '<td style="' + cell + '">' + esc(r.quote_id) + '</td>'
    + '<td style="' + cell + ';text-align:right">' + fmt(r.amount) + '</td>'
    + '<td style="' + cell + ';text-align:right">' + r.days + '</td></tr>').join('');
  return '<h3 style="margin:22px 0 2px">' + title + ' (' + list.length + ')</h3>'
    + '<p style="margin:0 0 8px;color:#666;font-size:13px">' + note + '</p>'
    + '<table style="border-collapse:collapse;font-size:14px;width:100%">'
    + '<tr><th align="left" style="' + head + '">Customer</th>'
    + '<th align="left" style="' + head + '">Quote</th>'
    + '<th align="right" style="' + head + '">Amount</th>'
    + '<th align="right" style="' + head + '">Days waiting</th></tr>' + trs + '</table>';
};

let html;
if (!rows.length) {
  html = '<p style="font-size:15px">Nothing is waiting on a reply this week — every quote in the sheet is won, lost, or has no usable send date.</p>';
} else {
  html = '<p style="font-size:15px">You have <b>' + rows.length + '</b> open quote' + (rows.length === 1 ? '' : 's')
    + ', and <b>' + fmt(valueAtRisk) + '</b> of that is sitting in quotes that have been quiet for ' + nudgeDays + '+ days.</p>'
    + section('Going cold', 'No answer for ' + coldDays + '+ days. Decide: chase once more, or mark it lost and free up the headspace.', cold)
    + section('Needs a nudge', 'Quiet for ' + nudgeDays + '-' + (coldDays - 1) + ' days. This is the week to follow up.', nudge)
    + section('Still fresh', 'Sent less than ' + nudgeDays + ' days ago. Leave them alone for now.', fresh);
}
if (skipped) {
  html += '<p style="margin-top:18px;color:#b45309;font-size:13px">' + skipped + ' open quote' + (skipped === 1 ? ' was' : 's were')
    + ' left out because their sent_date is missing, unreadable, or in the future. Fix those rows so they stop hiding.</p>';
}
html += '<p style="margin-top:26px;color:#888;font-size:12px">Week of ' + weekKey + ' · sent by your own n8n quote digest · nobody else received this email.</p>';

return [{
  json: {
    week_start: weekKey,
    already_sent: alreadySent,
    open_count: rows.length,
    skipped_rows: skipped,
    value_at_risk: Math.round(valueAtRisk * 100) / 100,
    needs_nudge: nudge.length,
    going_cold: cold.length,
    to: cfg.yourEmail,
    subject: 'Quotes waiting on a reply — week of ' + weekKey,
    html,
  },
}];

// Concrete keys only. The Sheets node maps plain input fields onto columns, so a column name
// built from an expression would be written as a literal instead of being evaluated.
const d = $('Build the weekly digest').first().json;
return [{
  json: {
    week_start: d.week_start,
    open_count: d.open_count,
    value_at_risk: d.value_at_risk,
    needs_nudge: d.needs_nudge,
    going_cold: d.going_cold,
    sent_at: $now.toFormat('yyyy-MM-dd HH:mm'),
  },
}];
